  "message": "#21 [stage-0 11/11] RUN --mount=type=secret,id=render-env,target=/run/secrets/render-env [\"/bin/bash\",\"-c\",\". /opt/bex/load-env\\nset -e\\ncat \u003e qa406-probe.cjs \u003c\u003c'QA406_QA406_PROBE_CJS'\\nconst fs=require('node:fs'),cp=require('node:child_process'),http=require('node:http'),crypto=require('node:crypto'),ref=require('./qa406-reference.json'),marker=require('./qa406-marker.json'),sha=b=\u003ecrypto.createHash('sha256').update(b).digest('hex');\\nconst files=Object.fromEntries(Object.keys(ref.files).map(p=\u003e{const b=fs.readFileSync(p);return[p,{bytes:b.length,sha256:sha(b)}]}));if(JSON.stringify(files)!==JSON.stringify(ref.files))throw Error('source differs');\\nfs.writeFileSync('qa406.ppm',Buffer.from(ref.input.base64,'base64'));const input=fs.readFileSync('qa406.ppm');if(sha(input)!==ref.input.sha256)throw Error('input differs');\\nfunction tools(){return Object.fromEntries(['convert','identify'].map(t=\u003e{const r=cp.spawnSync(t,['-version'],{encoding:'utf8',timeout:4000});return[t,{status:r.status,error:r.error?.code||null,stdout:r.stdout||'',stderr:r.stderr||''}]}))}\\nconst base={marker,files,input:{bytes:input.length,sha256:sha(input)},node:process.version,program_sha256:sha(fs.readFileSync(__filename))};\\nif(process.argv[2]==='before'){const v={...base,tools:tools()};fs.writeFileSync('qa406-before.json',JSON.stringify(v));console.log('QA406_BEFORE '+JSON.stringify(v));process.exit(0)}\\nfunction image(b){const rgb=cp.execFileSync('convert',['png:-','-depth','8','rgb:-'],{input:b,timeout:4000}),dimensions=cp.execFileSync('identify',['-format','%m %w %h','png:-'],{input:b,timeout:4000}).toString();if(dimensions!=='PNG 2 1'||rgb.toString('hex')!==ref.expected_rgb_hex)throw Error('pixels differ');return{...base,tools:tools(),png:{bytes:b.length,sha256:sha(b),signature:b.subarray(0,8).toString('hex'),dimensions},pixels:{hex:rgb.toString('hex'),sha256:sha(rgb)}}}\\nif(process.argv[2]==='build'){const v={...image(fs.readFileSync('qa406.png')),before:require('./qa406-before.json')};fs.writeFileSync('qa406-build.json',JSON.stringify(v));console.log('QA406_AFTER '+JSON.stringify(v));process.exit(0)}\\nconst built=require('./qa406-build.json');http.createServer((req,res)=\u003e{const b=cp.execFileSync('convert',['qa406.ppm','-filter','point','-resize','2x1!','-strip','PNG24:-'],{timeout:4000}),runtime={...image(b),request_url:req.url},v={build:built,runtime};res.setHeader('Cache-Control','no-store');res.setHeader('Content-Type',req.url.startsWith('/png')?'image/png':'application/json');res.end(req.url.startsWith('/png')?b:JSON.stringify(v));if(req.url.includes('qa406='))console.log('QA406_REQUEST '+JSON.stringify(v))}).listen(Number(process.env.PORT||10000),process.env.QA406_LOCAL?'127.0.0.1':'0.0.0.0',function(){console.log('QA406_READY '+JSON.stringify({port:this.address().port,...base}))});\\nQA406_QA406_PROBE_CJS\\ncat \u003e qa406-reference.json \u003c\u003c'QA406_QA406_REFERENCE_JSON'\\n{\"repo\":\"https://github.com/git-fixtures/basic\",\"branch\":\"master\",\"commit\":\"6ecf0ef2c2dffb796033e5a02219af86ec6584e5\",\"files\":{\"LICENSE\":{\"bytes\":1072,\"sha256\":\"20b064910b32bce1bc04595a5b20477a28c503995ef8528929a311d6cb7a3b09\"},\"CHANGELOG\":{\"bytes\":18,\"sha256\":\"9c65e366055edd9a0f6ab9c7b8a37fc92803cfe1d30ffa727ceed0c63939c2e5\"}},\"input\":{\"base64\":\"UDYKOCA0CjI1NQr/AAD/AAD/AAD/AAAAAP8AAP8AAP8AAP//AAD/AAD/AAD/AAAAAP8AAP8AAP8AAP//AAD/AAD/AAD/AAAAAP8AAP8AAP8AAP//AAD/AAD/AAD/AAAAAP8AAP8AAP8AAP8=\",\"bytes\":107,\"sha256\":\"f0c07ac4113c5586530c573852e3c51aad41d37e988eb7cad59d8282eced673e\"},\"expected_rgb_hex\":\"ff00000000ff\"}\\nQA406_QA406_REFERENCE_JSON\\ncat \u003e qa406-marker.json \u003c\u003c'QA406_QA406_MARKER_JSON'\\n\"QA406_fa0e11_render\"\\nQA406_QA406_MARKER_JSON\\nnode qa406-probe.cjs before\\nconvert qa406.ppm -filter point -resize 2x1! -strip PNG24:qa406.png\\nnode qa406-probe.cjs build\"]",
